{"cmd":"node - <<'NODE'
const fs = require('fs');
const path = require('path');
const dir = path.resolve('demo-data');
const load = (file) => JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
const vessels = load('vessels.json');
const voyages = load('voyages.json');
const ports = load('ports.json');
const people = load('people.json');
const manifest = load('source_manifest.json');
const errors = [];
const expectCount = (name, rows, count) => { if (rows.length !== count) errors.push(`${name} count ${rows.length} !== ${count}`); };
expectCount('vessels', vessels, 12);
expectCount('voyages', voyages, 30);
expectCount('ports', ports, 20);
expectCount('people', people, 25);
const vesselById = new Map(vessels.map(v => [v.vessel_id, v]));
const portById = new Map(ports.map(p => [p.port_id, p]));
const peopleById = new Map(people.map(p => [p.person_id, p]));
const requiredVoyageFields = ['voyage_id','vessel_name','imo','origin_port','destination_port','cargo','laycan_start','laycan_end','eta','etd','status'];
for (const voyage of voyages) {
  for (const field of requiredVoyageFields) {
    if (!voyage[field]) errors.push(`${voyage.voyage_id || '(missing id)'} missing ${field}`);
  }
  const vessel = vesselById.get(voyage.vessel_id);
  if (!vessel) errors.push(`${voyage.voyage_id} invalid vessel_id ${voyage.vessel_id}`);
  else {
    if (voyage.vessel_name !== vessel.vessel_name) errors.push(`${voyage.voyage_id} vessel_name mismatch`);
    if (voyage.imo !== vessel.imo) errors.push(`${voyage.voyage_id} imo mismatch`);
  }
  const origin = portById.get(voyage.origin_port_id);
  const dest = portById.get(voyage.destination_port_id);
  if (!origin) errors.push(`${voyage.voyage_id} invalid origin_port_id ${voyage.origin_port_id}`);
  else if (voyage.origin_port !== origin.port_name) errors.push(`${voyage.voyage_id} origin_port mismatch`);
  if (!dest) errors.push(`${voyage.voyage_id} invalid destination_port_id ${voyage.destination_port_id}`);
  else if (voyage.destination_port !== dest.port_name) errors.push(`${voyage.voyage_id} destination_port mismatch`);
  if (!peopleById.has(voyage.operations_contact_id)) errors.push(`${voyage.voyage_id} invalid operations_contact_id ${voyage.operations_contact_id}`);
}
if (manifest.files?.length !== 4) errors.push('manifest files length mismatch');
if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}
console.log('validation ok');
console.log(JSON.stringify({vessels:vessels.length,voyages:voyages.length,ports:ports.length,people:people.length}, null, 2));
NODE","workdir":"/Users/socrates/Documents/syntheci-shipping","yield_time_ms":1000,"max_output_tokens":4000}

