+const fs = require("fs");
+const path = require("path");
+
+const root = __dirname;
+const vessels = JSON.parse(fs.readFileSync(path.join(root, "vessels.json"), "utf8"));
+const voyages = JSON.parse(fs.readFileSync(path.join(root, "voyages.json"), "utf8"));
+const people = JSON.parse(fs.readFileSync(path.join(root, "people.json"), "utf8"));
+
+const outputDir = path.join(root, "emails");
+const outputFile = path.join(outputDir, "emails.json");
+
+const byPersonRole = new Map(people.map((person) => [person.role, person]));
+const byPersonId = new Map(people.map((person) => [person.person_id, person]));
+const byVesselName = new Map(vessels.map((vessel) => [vessel.vessel_name, vessel]));
+
+const internal = {
+  ops: byPersonRole.get("Voyage Coordinator"),
+  fleet: byPersonRole.get("Fleet Operations Manager"),
+  chartering: byPersonRole.get("Chartering Lead"),
+  bunker: byPersonRole.get("Bunker Procurement Specialist"),
+  claims: byPersonRole.get("Claims Analyst"),
+  hsqe: byPersonRole.get("HSQE Officer"),
+  finance: byPersonRole.get("Disbursement Accountant"),
+  performance: byPersonRole.get("Vessel Performance Analyst"),
+  legal: byPersonRole.get("Marine Insurance Coordinator"),
+  ets: {
+    name: "Helena Kyrkos",
+    email: "helena.kyrkos@aegeanmeridian.example",
+    role: "Regulatory Compliance Analyst"
+  }
+};
+
+const externalContacts = [
+  {
+    company: "BlueArc Chartering Ltd.",
+    domain: "bluearc-chartering.example",
+    contacts: [
+      { name: "Jonas Petrelli", role: "Chartering Broker" },
+      { name: "Clara Nguyen", role: "Post-Fixture Analyst" }
+    ]
+  },
+  {
+    company: "Harborline Port Agency",
+    domain: "harborline-agency.example",
+    contacts: [
+      { name: "Dimitra Lenos", role: "Port Agent" },
+      { name: "Arun Menon", role: "Operations Desk" }
+    ]
+  },
+  {
+    company: "Meridian Bunker Supply",
+    domain: "meridian-bunkers.example",
+    contacts: [
+      { name: "Hector Salvi", role: "Bunker Trader" },
+      { name: "Lina Farouk", role: "Claims Desk" }
+    ]
+  },
+  {
+    company: "Northstar Cargo Partners",
+    domain: "northstar-cargo.example",
+    contacts: [
+      { name: "Ariadne Fox", role: "Cargo Operations Manager" },
+      { name: "Victor Imani", role: "Claims Coordinator" }
+    ]
+  },
+  {
+    company: "ClearWake Emissions Advisory",
+    domain: "clearwake-advisory.example",
+    contacts: [
+      { name: "Marta Delling", role: "EU ETS Advisor" },
+      { name: "Theo Rens", role: "FuelEU Specialist" }
+    ]
+  },
+  {
+    company: "Quaywise Terminals",
+    domain: "quaywise-terminals.example",
+    contacts: [
+      { name: "Elias Brant", role: "Terminal Planner" },
+      { name: "Paula Serin", role: "Berth Scheduler" }
+    ]
+  }
+];
+
+function personAddress(person) {
+  return `${person.name} <${person.email}>`;
+}
+
+function externalAddress(companyIndex, contactIndex = 0) {
+  const company = externalContacts[companyIndex % externalContacts.length];
+  const contact = company.contacts[contactIndex % company.contacts.length];
+  const local = contact.name.toLowerCase().replace(/[^a-z]+/g, ".");
+  return `${contact.name} <${local}@${company.domain}>`;
+}
+
+function companyName(companyIndex) {
+  return externalContacts[companyIndex % externalContacts.length].company;
+}
+
+function addMinutes(date, minutes) {
+  return new Date(date.getTime() + minutes * 60000);
+}
+
+function formatDate(date) {
+  return date.toISOString().replace(".000Z", "Z");
+}
+
+function dateOnly(value) {
+  return value.slice(0, 10);
+}
+
+function makeAttachment(theme, voyage, threadNo, position) {
+  const vesselSlug = voyage.vessel_name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
+  const voyageSlug = voyage.voyage_id.toLowerCase();
+  const suffix = `${voyageSlug}-${String(threadNo).padStart(3, "0")}-${position + 1}`;
+  const common = {
+    voyage_update: [
+      ["Noon report", `noon-report-${vesselSlug}-${suffix}.pdf`, "application/pdf"],
+      ["Port rotation snapshot", `port-rotation-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Cargo operations timeline", `ops-timeline-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]
+    ],
+    bunker_confirmation: [
+      ["Bunker nomination", `bunker-nomination-${suffix}.pdf`, "application/pdf"],
+      ["BDN draft", `bdn-draft-${vesselSlug}-${suffix}.pdf`, "application/pdf"],
+      ["Sulphur certificate", `sulphur-certificate-${suffix}.pdf`, "application/pdf"]
+    ],
+    charterparty_revision: [
+      ["Charterparty markup", `cp-revision-${suffix}.docx`, "application/vnd.openxmlformats-officedocument.wordprocessingml.document"],
+      ["Fixture recap", `fixture-recap-${suffix}.pdf`, "application/pdf"],
+      ["Freight calculation", `freight-calc-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]
+    ],
+    eta_delay: [
+      ["Revised ETA notice", `revised-eta-${suffix}.pdf`, "application/pdf"],
+      ["Weather routing extract", `weather-routing-${suffix}.pdf`, "application/pdf"],
+      ["Speed and consumption log", `speed-consumption-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]
+    ],
+    port_congestion: [
+      ["Line-up report", `terminal-lineup-${suffix}.pdf`, "application/pdf"],
+      ["Berth prospects", `berth-prospects-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Agent update", `agent-update-${suffix}.pdf`, "application/pdf"]
+    ],
+    eu_ets_exposure: [
+      ["EU ETS exposure estimate", `eu-ets-exposure-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Allowance allocation note", `allowance-note-${suffix}.pdf`, "application/pdf"],
+      ["Emissions split worksheet", `emissions-split-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]
+    ],
+    fueleu_question: [
+      ["FuelEU compliance note", `fueleu-note-${suffix}.pdf`, "application/pdf"],
+      ["Fuel pathway summary", `fuel-pathway-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Supplier declaration draft", `supplier-declaration-${suffix}.pdf`, "application/pdf"]
+    ],
+    missing_mrv_fuel_data: [
+      ["MRV gap log", `mrv-gap-log-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Fuel consumption extract", `fuel-consumption-${suffix}.csv`, "text/csv"],
+      ["Engine room noon data", `engine-noon-data-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"]
+    ],
+    claims_demurrage_risk: [
+      ["Statement of facts", `sof-${suffix}.pdf`, "application/pdf"],
+      ["Laytime calculation", `laytime-calc-${suffix}.xlsx`, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
+      ["Notice of readiness", `nor-${suffix}.pdf`, "application/pdf"]
+    ]
+  };
+
+  const picked = common[theme][position % common[theme].length];
+  return {
+    attachment_id: `ATT-${String(threadNo).padStart(3, "0")}-${position + 1}`,
+    filename: picked[1],
+    description: picked[0],
+    content_type: picked[2],
+    synthetic: true
+  };
+}
+
+const themeOrder = [
+  "voyage_update",
+  "bunker_confirmation",
+  "charterparty_revision",
+  "eta_delay",
+  "port_congestion",
+  "eu_ets_exposure",
+  "fueleu_question",
+  "missing_mrv_fuel_data",
+  "claims_demurrage_risk"
+];
+
+const themeLabels = {
+  voyage_update: "Voyage update",
+  bunker_confirmation: "Bunker confirmation",
+  charterparty_revision: "Charterparty revision",
+  eta_delay: "ETA delay",
+  port_congestion: "Port congestion",
+  eu_ets_exposure: "EU ETS exposure",
+  fueleu_question: "FuelEU question",
+  missing_mrv_fuel_data: "Missing MRV fuel data",
+  claims_demurrage_risk: "Claims and demurrage risk"
+};
+
+function subjectFor(theme, voyage) {
+  const route = `${voyage.origin_port} / ${voyage.destination_port}`;
+  return `${themeLabels[theme]} - ${voyage.vessel_name} - ${voyage.voyage_id} - ${route}`;
+}
+
+function participantsFor(theme, voyage, threadNo, position) {
+  const contact = byPersonId.get(voyage.operations_contact_id) || internal.ops;
+  const agent = externalAddress(1, threadNo + position);
+  const broker = externalAddress(0, threadNo + position);
+  const bunker = externalAddress(2, threadNo + position);
+  const cargo = externalAddress(3, threadNo + position);
+  const advisor = externalAddress(4, threadNo + position);
+  const terminal = externalAddress(5, threadNo + position);
+  const maps = {
+    voyage_update: [contact, agent, internal.fleet],
+    bunker_confirmation: [internal.bunker, bunker, contact],
+    charterparty_revision: [internal.chartering, broker, internal.legal],
+    eta_delay: [contact, cargo, internal.fleet],
+    port_congestion: [agent, terminal, contact],
+    eu_ets_exposure: [internal.ets, advisor, internal.finance],
+    fueleu_question: [advisor, internal.ets, internal.hsqe],
+    missing_mrv_fuel_data: [internal.performance, contact, internal.hsqe],
+    claims_demurrage_risk: [internal.claims, cargo, internal.chartering]
+  };
+
+  const trio = maps[theme];
+  const sender = trio[position % trio.length];
+  const primary = trio[(position + 1) % trio.length];
+  const secondary = trio[(position + 2) % trio.length];
+
+  return {
+    from: typeof sender === "string" ? sender : personAddress(sender),
