+  const intro = position === 0 ? "Good day," : "Good day,\n\nFollowing the below,";
+  const signoff = "\n\nRegards,\nOperations Desk";
+  const etaDate = voyage.eta.replace("T", " ").replace(/:00[+-].*/, " local");
+  const etdDate = voyage.etd.replace("T", " ").replace(/:00[+-].*/, " local");
+
+  const templates = {
+    voyage_update: [
+      `${intro}\n\nPlease find the voyage update for ${voyage.vessel_name} on ${voyage.voyage_id}. The vessel is fixed from ${voyage.origin_port} to ${voyage.destination_port} with ${qty} of ${voyage.cargo}. Current ETD is ${etdDate} and ETA is ${etaDate}. Cargo readiness remains inside laycan ${voyage.laycan_start} to ${voyage.laycan_end}.${attachmentLine}${signoff}`,
+      `${intro} the master has confirmed no restriction on arrival draft and cargo documents are aligned with the current stowage plan. Please keep the berth window protected and advise if the receiver changes discharge sequence.${attachmentLine}${signoff}`,
+      `${intro} we have updated the port call checklist and marked customs pre-advice as pending. There is no change to commercial terms at this stage, and the current voyage status remains ${voyage.status}.${attachmentLine}${signoff}`,
+      `${intro} please confirm whether the receiver wants the cargo temperature log included in the arrival package. We will otherwise proceed with the standard arrival bundle and noon report only.${attachmentLine}${signoff}`,
+      `${intro} closing the loop for now. The next update will be sent after pilot boarding or if the ETA moves by more than six hours.${attachmentLine}${signoff}`
+    ],
+    bunker_confirmation: [
