    ]
  },
  {
    company: "Harborline Port Agency",
    domain: "harborline-agency.example",
    contacts: [
      { name: "Dimitra Lenos", role: "Port Agent" },
      { name: "Arun Menon", role: "Operations Desk" }
    ]
  },
  {
    company: "Meridian Bunker Supply",
    domain: "meridian-bunkers.example",
    contacts: [
      { name: "Hector Salvi", role: "Bunker Trader" },
      { name: "Lina Farouk", role: "Claims Desk" }
    ]
  },
  {
    company: "Northstar Cargo Partners",
    domain: "northstar-cargo.example",
    contacts: [
      { name: "Ariadne Fox", role: "Cargo Operations Manager" },
      { name: "Victor Imani", role: "Claims Coordinator" }
    ]
  },
  {
    company: "ClearWake Emissions Advisory",
    domain: "clearwake-advisory.example",
    contacts: [
      { name: "Marta Delling", role: "EU ETS Advisor" },
