      `${intro} the MRV gap is now closed for demo purposes. Please retain the corrected fuel extract with the voyage file and mark the original extract superseded.${attachmentLine}${signoff}`
    ],
    claims_demurrage_risk: [
      `${intro}\n\nThere is a potential demurrage risk on ${voyage.voyage_id} for ${voyage.vessel_name}. The concern relates to waiting time at ${voyage.destination_port} and whether NOR was validly tendered before berth availability.${attachmentLine}${signoff}`,
      `${intro} please preserve the statement of facts, NOR timestamp, pilot boarding time, and all terminal delay notices. We should not concede any delay cause until the agent confirms the berth log.${attachmentLine}${signoff}`,
      `${intro} preliminary laytime calculation shows exposure only if weather interruptions are disallowed. Please check the charterparty wording before we share any number externally.${attachmentLine}${signoff}`,
      `${intro} cargo interests dispute two waiting periods, but their position does not match the synthetic agent timeline. Please keep all correspondence factual and avoid admitting liability.${attachmentLine}${signoff}`,
      `${intro} claim risk remains manageable. We will accrue a conservative amount and revisit after discharge documents are finalized.${attachmentLine}${signoff}`
    ]
  };

  return templates[theme][position % templates[theme].length];
}

const threadLengths = [
  ...Array(5).fill(2),
  ...Array(10).fill(3),
  ...Array(15).fill(4),
  ...Array(20).fill(5)
];

const emails = [];
let emailNo = 1;

threadLengths.forEach((length, index) => {
  const threadNo = index + 1;
  const thread_id = `THR-2026-${String(threadNo).padStart(3, "0")}`;
  const theme = themeOrder[index % themeOrder.length];
  const voyage = voyages[index % voyages.length];
  const baseDate = addMinutes(new Date(voyage.etd), -720 + (index % 5) * 90);
  const subject = subjectFor(theme, voyage);

  for (let position = 0; position < length; position += 1) {
    const hasAttachment = position < Math.ceil(length * 0.6);
    const messageDate = addMinutes(baseDate, position * (210 + (index % 4) * 35));
    const participants = participantsFor(theme, voyage, threadNo, position);
    const attachments = hasAttachment ? [makeAttachment(theme, voyage, threadNo, position)] : [];
    const prefix = position === 0 ? "" : "Re: ";
    emails.push({
      email_id: `EML-2026-${String(emailNo).padStart(4, "0")}`,
      thread_id,
      subject: `${prefix}${subject}`,
      from: participants.from,
      to: participants.to,
      cc: participants.cc,
      date: formatDate(messageDate),
      body: bodyFor(theme, voyage, threadNo, position, length, hasAttachment),
      related_voyage_id: voyage.voyage_id,
      related_vessel_name: voyage.vessel_name,
      attachments
    });
    emailNo += 1;
  }
});

