const fs = require("fs");
const path = require("path");

const root = __dirname;
const documentsDir = path.join(root, "documents");
const emailsPath = path.join(root, "emails", "emails.json");
const voyagesPath = path.join(root, "voyages.json");
const vesselsPath = path.join(root, "vessels.json");

const emails = JSON.parse(fs.readFileSync(emailsPath, "utf8"));
const voyages = JSON.parse(fs.readFileSync(voyagesPath, "utf8"));
const vessels = JSON.parse(fs.readFileSync(vesselsPath, "utf8"));

const voyageById = new Map(voyages.map((voyage) => [voyage.voyage_id, voyage]));
const vesselByName = new Map(vessels.map((vessel) => [vessel.vessel_name, vessel]));

const targets = [
  ["voyage_order", 40],
  ["bunker_fuel_document", 40],
  ["charterparty_excerpt", 20],
  ["compliance_sop", 10],
  ["port_weather_notice", 15],
  ["claims_note", 10]
];

const documentTypeLabels = {
  voyage_order: "Voyage Order",
  bunker_fuel_document: "Bunker/Fuel Document",
  charterparty_excerpt: "Charterparty Excerpt",
  compliance_sop: "Compliance SOP",
  port_weather_notice: "Port/Weather Notice",
  claims_note: "Claims Note"
};

const docTypeDescriptions = {
  voyage_order: "voyage instructions, cargo handling expectations, arrival notices, and operational routing details",
  bunker_fuel_document: "bunker confirmations, fuel evidence, BDN checks, consumption reconciliation, and MRV fuel data",
  charterparty_excerpt: "fixture terms, rider clauses, laytime language, allocation rules, and charterparty revision notes",
  compliance_sop: "EU ETS, FuelEU, MRV, and emissions-control procedures for synthetic demo workflows",
  port_weather_notice: "berth prospects, congestion notices, weather routing updates, and terminal operating constraints",
  claims_note: "demurrage exposure, notices of readiness, statements of fact, and claims-preservation guidance"
};

function slug(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function mdEscape(value) {
  return String(value).replace(/\|/g, "\\|");
}

function dateOnly(value) {
  return value.slice(0, 10);
}

function localDateTime(value) {
  return value.replace("T", " ").replace(/:00[+-].*/, " local");
}

function attachmentTheme(email, attachment) {
  const text = `${email.subject} ${attachment.description} ${attachment.filename}`.toLowerCase();
  if (text.includes("bunker") || text.includes("bdn") || text.includes("sulphur") || text.includes("fuel") || text.includes("mrv") || text.includes("engine") || text.includes("noon")) {
    return "fuel";
  }
  if (text.includes("charterparty") || text.includes("fixture") || text.includes("freight") || text.includes("cp-")) {
    return "charterparty";
  }
  if (text.includes("eu ets") || text.includes("fueleu") || text.includes("allowance") || text.includes("emissions") || text.includes("supplier declaration")) {
    return "compliance";
  }
  if (text.includes("congestion") || text.includes("weather") || text.includes("berth") || text.includes("terminal") || text.includes("agent") || text.includes("eta")) {
    return "port_weather";
  }
  if (text.includes("claims") || text.includes("demurrage") || text.includes("laytime") || text.includes("statement of facts") || text.includes("sof") || text.includes("notice of readiness") || text.includes("nor")) {
    return "claims";
  }
  return "voyage";
}

function preferredTypes(email, attachment) {
  const theme = attachmentTheme(email, attachment);
  const map = {
    fuel: ["bunker_fuel_document", "voyage_order", "compliance_sop", "charterparty_excerpt"],
    charterparty: ["charterparty_excerpt", "voyage_order", "claims_note", "compliance_sop"],
    compliance: ["compliance_sop", "bunker_fuel_document", "charterparty_excerpt", "voyage_order"],
    port_weather: ["port_weather_notice", "voyage_order", "claims_note", "charterparty_excerpt"],
    claims: ["claims_note", "charterparty_excerpt", "port_weather_notice", "voyage_order"],
    voyage: ["voyage_order", "port_weather_notice", "bunker_fuel_document", "charterparty_excerpt"]
  };
  return map[theme];
}

function collectAttachments() {
  const rows = [];
  for (const email of emails) {
    for (const attachment of email.attachments) {
      rows.push({ email, attachment });
    }
  }
  return rows;
}

function allocateTypes(rows) {
  const remaining = new Map(targets);
  const assignments = new Map();

  for (const type of targets.map(([name]) => name)) {
    for (const row of rows) {
      if (remaining.get(type) === 0) break;
      if (assignments.has(row.attachment.attachment_id)) continue;
      if (preferredTypes(row.email, row.attachment)[0] === type) {
        assignments.set(row.attachment.attachment_id, type);
        remaining.set(type, remaining.get(type) - 1);
      }
    }
  }

  for (const row of rows) {
    if (assignments.has(row.attachment.attachment_id)) continue;
    const type = preferredTypes(row.email, row.attachment).find((candidate) => remaining.get(candidate) > 0)
      || targets.find(([candidate]) => remaining.get(candidate) > 0)?.[0];
    if (!type) throw new Error("No remaining document type capacity");
    assignments.set(row.attachment.attachment_id, type);
    remaining.set(type, remaining.get(type) - 1);
  }

  for (const [type, count] of remaining) {
    if (count !== 0) throw new Error(`Document type allocation mismatch for ${type}: ${count} remaining`);
  }
  return assignments;
}

function metadataBlock(metadata) {
  return [
    "---",
    `document_id: ${metadata.document_id}`,
    `document_type: ${metadata.document_type}`,
    `related_voyage_id: ${metadata.related_voyage_id}`,
    `related_vessel_name: ${metadata.related_vessel_name}`,
    `source_email_id: ${metadata.source_email_id}`,
    `created_at: ${metadata.created_at}`,
    `source_attachment_id: ${metadata.source_attachment_id}`,
    `original_attachment_filename: ${metadata.original_attachment_filename}`,
    "---"
  ].join("\n");
}

function routeTable(voyage, vessel) {
  return [
    "| Field | Value |",
    "| --- | --- |",
    `| Vessel | ${mdEscape(voyage.vessel_name)} |`,
    `| IMO | ${mdEscape(voyage.imo)} |`,
    `| Vessel type | ${mdEscape(vessel?.vessel_type || "Synthetic vessel")} |`,
    `| Voyage | ${mdEscape(voyage.voyage_id)} |`,
    `| Origin | ${mdEscape(voyage.origin_port)} |`,
    `| Destination | ${mdEscape(voyage.destination_port)} |`,
    `| Cargo | ${mdEscape(voyage.cargo)} |`,
    `| Laycan | ${mdEscape(voyage.laycan_start)} to ${mdEscape(voyage.laycan_end)} |`,
    `| ETD | ${mdEscape(localDateTime(voyage.etd))} |`,
    `| ETA | ${mdEscape(localDateTime(voyage.eta))} |`,
    `| Voyage status | ${mdEscape(voyage.status)} |`
  ].join("\n");
}

function attachmentContext(email, attachment) {
  return [
    `This document was generated for source email ${email.email_id} in thread ${email.thread_id}.`,
    `Email subject: "${email.subject}".`,
    `Original synthetic attachment: ${attachment.filename} (${attachment.description}).`
  ].join(" ");
}

function voyageOrderContent(voyage, vessel, email, attachment) {
  return [
    "## Voyage Instructions",
    "",
    `Aegean Meridian Shipping issues this synthetic voyage order for ${voyage.vessel_name} under ${voyage.voyage_id}. The vessel is to proceed from ${voyage.origin_port} to ${voyage.destination_port} with ${voyage.cargo}. The operational objective is to keep the vessel inside the agreed laycan window, preserve berth readiness evidence, and maintain a clean document trail for post-fixture review.`,
    "",
    routeTable(voyage, vessel),
    "",
    "## Required Actions",
    "",
    "- Confirm cargo readiness with the nominated terminal before arrival and record the name of the confirming party.",
    "- Maintain noon reports, arrival notices, cargo operation times, and any deviation notices in the voyage file.",
    "- Notify the operations desk if ETA changes by more than six hours, if berth prospects deteriorate, or if draft restrictions are imposed.",
    "- Keep emissions, bunker, and cargo documents separate by source so Syntheci can retrieve each evidence type independently.",
    "",
    "## RAG Retrieval Notes",
    "",
    `Useful retrieval phrases include "${voyage.vessel_name} voyage order", "${voyage.voyage_id} cargo ${voyage.cargo}", "${voyage.origin_port} to ${voyage.destination_port}", "laycan ${voyage.laycan_start}", and "ETA ${dateOnly(voyage.eta)}".`,
    "",
    "## Source Context",
    "",
    attachmentContext(email, attachment)
  ].join("\n");
}

function bunkerFuelContent(voyage, vessel, email, attachment) {
  const isContainer = vessel?.vessel_type?.includes("Container");
  const fuelLine = isContainer ? "VLSFO stem plus MGO for auxiliary consumption" : "VLSFO/MGO stem and ROB reconciliation";
  return [
    "## Bunker and Fuel Evidence",
    "",
    `This synthetic bunker/fuel document supports ${voyage.voyage_id} for ${voyage.vessel_name}. It captures fuel planning and reconciliation items relevant to ${voyage.cargo} carried between ${voyage.origin_port} and ${voyage.destination_port}. The document is intended for retrieval against bunker invoice, BDN, sulphur certificate, MRV fuel data, noon report, and emissions evidence questions.`,
    "",
    routeTable(voyage, vessel),
    "",
    "## Fuel Data Points",
    "",
    `- Fuel scope: ${fuelLine}.`,
    "- Required evidence: bunker delivery note, supplier declaration where applicable, sample seal references, sulphur value, density, viscosity, and final ROB.",
    "- MRV handling: separate main engine, auxiliary engine, and boiler consumption. Do not combine auxiliary and boiler figures in the final evidence pack.",
    "- Invoice check: confirm delivery location, delivery date, nominated supplier, agreed quantity, received quantity, and any waiting-time line items.",
    "- Operational dependency: fuel evidence must reconcile with noon reports and any speed instruction issued after departure.",
    "",
    "## Exceptions and Follow-up",
    "",
    `If final figures are missing for ${voyage.vessel_name}, mark the voyage file as provisional and request corrected consumption for the period after ETD ${localDateTime(voyage.etd)}. Any amended BDN or invoice should be cross-referenced to ${voyage.voyage_id} and the original email thread.`,
    "",
    "## Source Context",
    "",
    attachmentContext(email, attachment)
  ].join("\n");
}

function charterpartyContent(voyage, vessel, email, attachment) {
  return [
    "## Charterparty Excerpt",
    "",
    `This fictional charterparty excerpt relates to ${voyage.voyage_id} for ${voyage.vessel_name}. It summarizes commercial clauses likely to be queried during post-fixture operations, including laycan, cargo description, EU ETS allocation, FuelEU evidence, document timing, and demurrage handling. It is not a live fixture and has no legal force.`,
    "",
    routeTable(voyage, vessel),
    "",
    "## Excerpted Clauses",
    "",
    `1. Cargo: ${voyage.cargo} to be loaded at ${voyage.origin_port} and discharged at ${voyage.destination_port}, subject to terminal acceptance and vessel suitability.`,
    `2. Laycan: Owners to present the vessel within ${voyage.laycan_start} to ${voyage.laycan_end}; charterers to keep cargo and berth prospects updated in writing.`,
    "3. Laytime evidence: notice of readiness, statement of facts, pilot times, berth times, weather stoppages, and terminal delay notices are to be retained in the voyage file.",
    "4. Emissions evidence: MRV fuel data, bunker documentation, and any EU ETS or FuelEU supporting calculations are to be exchanged after completion of discharge.",
    "5. Demurrage reservation: neither party waives rights by exchanging operational estimates before final laytime calculation.",
    "",
    "## Retrieval Guidance",
    "",
    `Search terms: ${voyage.voyage_id} charterparty, ${voyage.vessel_name} laycan, ${voyage.destination_port} demurrage, EU ETS allocation, FuelEU evidence, and ${voyage.cargo} cargo clause.`,
    "",
    "## Source Context",
    "",
    attachmentContext(email, attachment)
  ].join("\n");
}

function complianceContent(voyage, vessel, email, attachment) {
  return [
    "## Compliance SOP",
    "",
    `This synthetic compliance SOP explains how Aegean Meridian Shipping handles EU ETS, FuelEU, and MRV evidence for ${voyage.voyage_id} on ${voyage.vessel_name}. It is written for demo retrieval and citation scenarios, not for regulatory filing.`,
    "",
    routeTable(voyage, vessel),
    "",
    "## Procedure",
    "",
    "1. Confirm whether the voyage leg is in scope for the relevant demo compliance workflow.",
    "2. Collect bunker delivery notes, fuel certificates, noon reports, ROB statements, and any supplier fuel pathway declarations.",
    "3. Separate EU ETS allowance exposure from FuelEU greenhouse gas intensity assumptions. Treat them as related but distinct workflows.",
    "4. Use provisional calculations only until final MRV fuel consumption has been reconciled after discharge.",
    "5. Store the compliance note with the voyage file and reference the source email that requested the calculation or clarification.",
    "",
    "## Controls",
    "",
