    "- Escalate missing MRV fuel data before month close if finance or chartering relies on exposure estimates.",
    "",
    "## Source Context",
    "",
    attachmentContext(email, attachment)
  ].join("\n");
}

function portWeatherContent(voyage, vessel, email, attachment) {
  return [
    "## Port and Weather Notice",
    "",
    `This synthetic notice covers operational conditions affecting ${voyage.vessel_name} during ${voyage.voyage_id}. It is designed to answer questions about ETA delay, berth prospects, congestion, weather routing, terminal line-up, and port call risk.`,
