const contentByType = {
  voyage_order: voyageOrderContent,
  bunker_fuel_document: bunkerFuelContent,
  charterparty_excerpt: charterpartyContent,
  compliance_sop: complianceContent,
  port_weather_notice: portWeatherContent,
  claims_note: claimsContent
};

function main() {
  const rows = collectAttachments();
  const assignments = allocateTypes(rows);
  if (rows.length !== 135) {
    throw new Error(`Expected 135 attachments, found ${rows.length}`);
  }

  fs.mkdirSync(documentsDir, { recursive: true });
  for (const file of fs.readdirSync(documentsDir)) {
    if (file.endsWith(".md")) fs.unlinkSync(path.join(documentsDir, file));
  }

  let docNo = 1;
  const counts = new Map(targets.map(([type]) => [type, 0]));
  const updatedEmails = emails.map((email) => ({
    ...email,
    attachments: email.attachments.map((attachment) => {
      const documentType = assignments.get(attachment.attachment_id);
      const voyage = voyageById.get(email.related_voyage_id);
      const vessel = vesselByName.get(email.related_vessel_name);
      if (!voyage) throw new Error(`Invalid voyage ${email.related_voyage_id}`);
      const documentId = `DOC-2026-${String(docNo).padStart(4, "0")}`;
      const filename = `${documentId.toLowerCase()}-${slug(documentType)}-${slug(voyage.voyage_id)}.md`;
      const createdAt = email.date;
      const metadata = {
        document_id: documentId,
        document_type: documentType,
        related_voyage_id: voyage.voyage_id,
        related_vessel_name: voyage.vessel_name,
        source_email_id: email.email_id,
        created_at: createdAt,
        source_attachment_id: attachment.attachment_id,
        original_attachment_filename: attachment.original_filename || attachment.filename
      };
      const body = [
        metadataBlock(metadata),
        "",
        `# ${documentTypeLabels[documentType]} - ${voyage.vessel_name} - ${voyage.voyage_id}`,
        "",
        `Document purpose: ${docTypeDescriptions[documentType]}.`,
        "",
        contentByType[documentType](voyage, vessel, email, attachment),
        "",
        "## Synthetic Data Notice",
        "",
        "This markdown document is fictional demo data for Syntheci. It does not contain real company confidential data, real vessel registry data, or live compliance advice."
      ].join("\n");

      fs.writeFileSync(path.join(documentsDir, filename), `${body}\n`);
      counts.set(documentType, counts.get(documentType) + 1);
      docNo += 1;

      return {
        ...attachment,
        document_id: documentId,
        document_type: documentType,
        original_filename: attachment.original_filename || attachment.filename,
        filename,
        path: `demo-data/documents/${filename}`,
        content_type: "text/markdown"
      };
    })
  }));

  fs.writeFileSync(emailsPath, `${JSON.stringify(updatedEmails, null, 2)}\n`);

  console.log(`Generated ${docNo - 1} markdown documents`);
  console.log(Object.fromEntries(counts));
}

main();

