const fs = require("fs");
const path = require("path");

const root = __dirname;
const outDir = path.join(root, "structured");
const voyages = JSON.parse(fs.readFileSync(path.join(root, "voyages.json"), "utf8"));
const vessels = JSON.parse(fs.readFileSync(path.join(root, "vessels.json"), "utf8"));
const ports = JSON.parse(fs.readFileSync(path.join(root, "ports.json"), "utf8"));

const vesselByName = new Map(vessels.map((vessel) => [vessel.vessel_name, vessel]));

const portCoords = {
  "Thalassa Gate Terminal": [37.94, 23.63],
  "Nereid Bay Port": [37.43, 24.92],
  "Kydonia Container Quay": [35.52, 24.02],
  "Maris Grain Pier": [41.25, 16.89],
  "Vela Ro-Ro Berth": [40.46, 17.24],
  "Ionia Liquid Terminal": [34.69, 33.08],
  "Caldera Energy Port": [36.37, 25.48],
  "Ormos Multipurpose Dock": [36.44, 28.22],
  "Helike Oil Terminal": [38.22, 22.11],
  "Azure Strait Terminal": [35.89, 14.51],
  "Sirocco Bulk Terminal": [36.83, 10.31],
  "Lykos Cold Port": [38.42, 27.13],
  "Anemos Marine Terminal": [43.52, 16.46],
  "Selene Container Yard": [31.25, 29.92],
  "Minoa Cement Wharf": [35.33, 25.14],
  "Pontus Steel Dock": [40.77, 29.74],
  "Koralia Fruit Terminal": [35.11, 33.95],
  "Eurus Auto Quay": [39.45, -0.31],
  "Daphne Fertilizer Jetty": [35.81, -5.55],
  "Argos Bunkering Station": [37.87, 23.49]
};

const suppliers = [
  "Meridian Bunker Supply",
  "Aster Fuel Trading",
  "HelioMarine Energy",
  "BlueWake Bunkers",
  "Caldera Marine Fuels",
  "Ionia Energy Desk"
];

const fuelByVesselType = {
  "Product tanker": ["VLSFO", "MGO"],
  "Bulk carrier": ["VLSFO", "MGO"],
  "Container feeder": ["VLSFO", "MGO"],
  "Handymax bulk carrier": ["VLSFO", "MGO"],
  "Ro-ro cargo": ["VLSFO", "MGO"],
  "Chemical tanker": ["VLSFO", "MGO"],
  "LNG bunkering vessel": ["LNG", "MGO"],
  "General cargo": ["VLSFO", "MGO"],
  "Crude oil tanker": ["VLSFO", "MGO"],
  "Supramax bulk carrier": ["VLSFO", "MGO"],
  "Reefer cargo": ["VLSFO", "MGO"]
};

const co2Factors = {
  VLSFO: 3.114,
  MGO: 3.206,
  LNG: 2.75
};

function addHours(date, hours) {
  return new Date(date.getTime() + hours * 3600000);
}

function iso(date) {
  return date.toISOString().replace(".000Z", "Z");
}

function csvEscape(value) {
  const text = String(value);
  if (/[",\n]/.test(text)) return `"${text.replace(/"/g, '""')}"`;
  return text;
}

function writeCsv(file, rows, headers) {
  const lines = [headers.join(",")];
  for (const row of rows) {
    lines.push(headers.map((header) => csvEscape(row[header])).join(","));
  }
  fs.writeFileSync(path.join(outDir, file), `${lines.join("\n")}\n`);
}

function interpolate(start, end, fraction) {
  const latWave = Math.sin(fraction * Math.PI) * 0.18;
  const lngWave = Math.cos(fraction * Math.PI) * 0.12;
  return [
    start[0] + (end[0] - start[0]) * fraction + latWave,
    start[1] + (end[1] - start[1]) * fraction + lngWave
  ];
}

function headingBetween(start, end) {
  const dy = end[0] - start[0];
  const dx = end[1] - start[1];
  const radians = Math.atan2(dx, dy);
  return Math.round((radians * 180 / Math.PI + 360) % 360);
}

function distanceScore(voyage) {
  const start = portCoords[voyage.origin_port];
  const end = portCoords[voyage.destination_port];
  const dLat = end[0] - start[0];
  const dLng = end[1] - start[1];
  return Math.sqrt(dLat * dLat + dLng * dLng);
}

function fuelQuantity(voyage, vessel, fuelType, index) {
  const base = vessel.dwt > 100000 ? 720 : vessel.dwt > 60000 ? 470 : vessel.dwt > 30000 ? 320 : 180;
  const distance = distanceScore(voyage);
  const factor = fuelType === "MGO" ? 0.12 : fuelType === "LNG" ? 0.72 : 1;
  return Number((base * factor + distance * 22 + (index % 5) * 14).toFixed(2));
}

function sulfurPct(fuelType, index) {
  if (fuelType === "LNG") return 0.001;
  if (fuelType === "MGO") return Number((0.04 + (index % 4) * 0.005).toFixed(3));
  return Number((0.43 + (index % 5) * 0.012).toFixed(3));
}

function activeVoyages() {
  return voyages.filter((voyage) => ["arrived", "in_transit", "loading", "scheduled"].includes(voyage.status));
}

function generateBunkerReports() {
  const rows = [];
  let invoiceNo = 1;
  voyages.forEach((voyage, index) => {
    const vessel = vesselByName.get(voyage.vessel_name);
    const fuelTypes = fuelByVesselType[vessel.vessel_type] || ["VLSFO", "MGO"];
    const count = index % 3 === 0 ? 2 : 1;
    for (let i = 0; i < count; i += 1) {
      const fuelType = fuelTypes[i % fuelTypes.length];
      const deliveryDate = addHours(new Date(voyage.etd), -18 + i * 5);
      rows.push({
        vessel: voyage.vessel_name,
        voyage_id: voyage.voyage_id,
        fuel_type: fuelType,
        quantity_mt: fuelQuantity(voyage, vessel, fuelType, index + i),
        sulfur_pct: sulfurPct(fuelType, index + i),
        co2_factor: co2Factors[fuelType],
        port: i === 0 ? voyage.origin_port : "Argos Bunkering Station",
        supplier: suppliers[(index + i) % suppliers.length],
        invoice_id: `BINV-2026-${String(invoiceNo).padStart(4, "0")}`,
        date: iso(deliveryDate).slice(0, 10)
      });
      invoiceNo += 1;
    }
  });
  return rows;
}

function generateAisPositions() {
  const rows = [];
  let positionNo = 1;
  for (const voyage of activeVoyages()) {
    const start = portCoords[voyage.origin_port];
    const end = portCoords[voyage.destination_port];
    const heading = headingBetween(start, end);
    const etd = new Date(voyage.etd);
    const eta = new Date(voyage.eta);
    const durationHours = Math.max(12, (eta.getTime() - etd.getTime()) / 3600000);
    for (let i = 0; i < 6; i += 1) {
      const fraction = (i + 1) / 7;
      const [lat, lng] = interpolate(start, end, fraction);
      const timestamp = addHours(etd, durationHours * fraction);
      rows.push({
        position_id: `AIS-2026-${String(positionNo).padStart(5, "0")}`,
        voyage_id: voyage.voyage_id,
        vessel_name: voyage.vessel_name,
        lat: Number(lat.toFixed(5)),
        lng: Number(lng.toFixed(5)),
        speed_knots: Number((10.8 + (positionNo % 7) * 0.7).toFixed(1)),
        heading: (heading + (i - 2) * 3 + 360) % 360,
        timestamp: iso(timestamp),
        destination: voyage.destination_port,
        eta: voyage.eta
      });
      positionNo += 1;
    }
  }
  return rows;
}

function generateVoyageEvents() {
  const rows = [];
  let eventNo = 1;
  const eventTypes = ["port_call", "delay_event", "canal_transit", "weather_event", "bunker_stop"];
  voyages.forEach((voyage, index) => {
    const base = new Date(voyage.etd);
    const candidates = [
      {
        event_type: "port_call",
        event_time: iso(addHours(base, -3)),
        location: voyage.origin_port,
        severity: "info",
        description: `${voyage.vessel_name} completed pre-departure port call formalities for ${voyage.cargo}.`
      },
      {
        event_type: "bunker_stop",
        event_time: iso(addHours(base, -12)),
        location: voyage.origin_port,
        severity: index % 5 === 0 ? "watch" : "info",
        description: `Synthetic bunker stop recorded before sailing from ${voyage.origin_port}; BDN pending final reconciliation.`
      },
      {
        event_type: "weather_event",
        event_time: iso(addHours(base, 18 + (index % 6) * 4)),
        location: "At sea",
        severity: index % 4 === 0 ? "medium" : "watch",
        description: `Weather routing update issued for ${voyage.vessel_name}; speed may be adjusted to protect ETA at ${voyage.destination_port}.`
      },
      {
        event_type: "delay_event",
        event_time: iso(addHours(new Date(voyage.eta), -8)),
        location: voyage.destination_port,
        severity: index % 3 === 0 ? "high" : "medium",
        description: `Potential delay exposure at ${voyage.destination_port} due to berth line-up or cargo readiness uncertainty.`
      },
      {
        event_type: "canal_transit",
        event_time: iso(addHours(base, 30 + (index % 5) * 7)),
        location: index % 2 === 0 ? "Aegean Meridian Traffic Scheme" : "Synthetic Strait Transit",
        severity: "info",
