        vessel_name: voyage.vessel_name,
        ...event
      });
      eventNo += 1;
    }
  });
  return rows;
}

function generateComplianceFlags(bunkerRows) {
  const bunkerByVoyage = new Map();
  for (const report of bunkerRows) {
    if (!bunkerByVoyage.has(report.voyage_id)) bunkerByVoyage.set(report.voyage_id, []);
    bunkerByVoyage.get(report.voyage_id).push(report);
