 else if (voyage.vessel_name !== scn.primary_vessel_name) errors.push(`${scn.scenario_id} vessel mismatch`);
 for (const id of scn.evidence.threads || []) if (!threadIds.has(id)) errors.push(`${scn.scenario_id} invalid thread ${id}`);
